const peoplePhotos={'我':avatar,'小满':photo('photo-1524504388940-b1c1722653e1',100),'阿远':photo('photo-1500648767791-00dcc994a43e',100),'阿禾':photo('photo-1506794778202-cad84cf45f1d',100)};
function personFace(name,cls='avatar'){return `<img class="${cls}" src="${peoplePhotos[name]||avatar}" alt="${esc(name)}" title="${esc(name)}">`}
function participantFaces(people){return `<div class="participants"><span>一起的人</span><div class="face-stack">${people.split(/[、,，]/).filter(Boolean).map(n=>personFace(n.trim())).join('')}</div></div>`}
function coverHero(src,title,subtitle,extra=''){document.querySelector('.phone').classList.remove('immersive');return backbar(title,extra)+`<section class="plain-cover"><img id="cover" src="${src}" alt="${esc(title)}"><div><span class="sub">${subtitle}</span><h1>${esc(title)}</h1></div></section>`}
const communityExamples=[{id:100,title:'今天的风，刚刚好',text:'把忙碌留在城市，把今天留在这里。下次一起。',images:[imgs[5],imgs[0],imgs[2]],date:'2026-10-26',place:'湖边',author:'小满'},{id:101,title:'收集秋天的颜色',text:'沿着小路走了很久，拍下这些舍不得错过的光。',images:[imgs[1],imgs[4],imgs[2],imgs[5]],date:'2026-10-25',place:'九溪',author:'阿远'},{id:102,title:'我们的周末放映室',text:'从山野到湖边，镜头里的每一帧都很喜欢。',images:[imgs[2],imgs[3],imgs[0]],date:'2026-10-24',place:'杭州',author:'阿禾'}];
const seedComments={100:[['阿远','这个光线太美了，下次一起！'],['小满','好呀，等一个晴天。']],101:[['阿禾','第二张好像电影画面。']],102:[['小满','把普通的日子过成了喜欢的样子。']]};
function post(m,author){let likers=m.id%2?['小满','阿禾']:['阿远','小满'];if(likes[m.id])likers=['我',...likers];return `<article class="post" id="post-${m.id}"><div class="post-head">${personFace(author)}<div><b>${esc(author)}</b><small>${m.date.slice(5).replace('-','.')} · ${esc(m.place)}</small></div></div><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p>${m.images.length?gallery(m,'community-gallery'):''}<div class="actions"><button class="${likes[m.id]?'liked':''}" aria-label="${likes[m.id]?'取消喜欢':'喜欢'}" onclick="togglePostLike(${m.id},this)">${icon('heart')} ${likes[m.id]?'已喜欢':'喜欢'}</button><button onclick="commentSheet(${m.id})">${icon('comment')} 评论 ${(seedComments[m.id]?.length||0)+(comments[m.id]?.length||0)}</button><span class="sub" style="margin-left:auto">${esc(selectedCircle)}可见</span></div><div class="liker-row"><div class="face-stack">${likers.map(n=>personFace(n)).join('')}</div><span>${likers.map(esc).join('、')} 喜欢了</span></div><div class="comment-thread">${(seedComments[m.id]||[]).map(([n,s])=>`<div class="comment-line">${personFace(n)}<div><b>${n}</b><span>${esc(s)}</span></div></div>`).join('')}${(comments[m.id]||[]).map(s=>`<div class="comment-line">${personFace('我')}<div><b>我</b><span>${esc(s)}</span></div></div>`).join('')}</div></article>`}
function togglePostLike(id,button){likes[id]=!likes[id];let m=memories.find(m=>m.id===id)||communityExamples.find(m=>m.id===id);let holder=document.createElement('div');holder.innerHTML=post(m,m.author||'我');$('#post-'+id).replaceWith(holder.firstElementChild)}
function customField(key,label,value){return `<div class="custom-field"><span>${label}</span><button type="button" class="field-select" aria-label="${label}" aria-haspopup="dialog" onclick="openField('${key}')"><span>${esc(value)}</span>${icon('back').replace('<svg ','<svg class="chevron-down" ')}</button></div>`}
function editor(){document.querySelector('.phone').classList.remove('immersive');closeSheet();$('#nav').style.display='none';draft.tag??='日常碎片';draft.mood??='开心';draft.date??='2026-11-01';draft.scope??=[];app.innerHTML=`<div class="backbar">${ib('back','cancelEdit()','取消编辑')}<b>${draft.id?'编辑瞬间':'新的瞬间'}</b><button class="primary" style="padding:7px 18px;min-height:36px" onclick="publish()">${draft.id?'保存':'发布'}</button></div><div class="form editor-form"><div class="preview-images">${(draft.images||[]).map(src=>`<img src="${src}" alt="待发布照片">`).join('')}<button class="secondary" aria-label="添加照片" onclick="captureDraft();pickForDraft()">${icon('plus')}</button></div><label>标题<input id="title" class="title-input" maxlength="60" value="${esc(draft.title||'')}" placeholder="给这个瞬间起个名字"></label><label>记录此刻<textarea id="body" placeholder="今天，有什么想记住的？">${esc(draft.text||'')}</textarea></label>${customField('tag','标签',draft.tag)}${customField('mood','此刻心情',draft.mood)}${customField('date','记忆时间',draft.date)}<label>地点<input id="place" value="${esc(draft.place||'')}" placeholder="你在哪里"></label><label>一起的人<input id="people" value="${esc(draft.people||'')}" placeholder="用顿号分隔参与者"></label>${customField('trip','关联同行',draft.trip||'不关联同行')}${customField('scope','可见范围',draft.scope.length?draft.scope.join('、'):'私人 · 仅自己可见')}<p class="sub">${icon('lock')} 你的记录，由你决定谁能看见。</p></div>`;app.scrollTop=0}
function captureDraft(){draft={...draft,title:$('#title').value,text:$('#body').value,place:$('#place').value,people:$('#people').value}}
let editorScroll=0,fieldOptions=[],pendingScope=[];
function openField(key){captureDraft();editorScroll=app.scrollTop;if(key==='date'){openCalendar();return}if(key==='scope'){pendingScope=[...draft.scope];scopeMenu();return}fieldOptions=key==='tag'?['日常碎片','出走日记','山野之间']:key==='mood'?Object.keys(moodStyles):['',...trips.map(t=>t.name)];let title={tag:'选择标签',mood:'选择此刻心情',trip:'关联同行'}[key];sheet(`<h2>${title}</h2><div class="choice-list" role="listbox" aria-label="${title}">${fieldOptions.map((value,i)=>`<button class="choice-option ${draft[key]===value?'chosen':''}" role="option" aria-selected="${draft[key]===value}" onclick="chooseField('${key}',${i})"><span>${key==='mood'?moodBadge(value):esc(value||'不关联同行')}</span><i class="choice-mark">${draft[key]===value?'✓':''}</i></button>`).join('')}</div>`)}
function chooseField(key,i){draft[key]=fieldOptions[i];returnEditor()}
function returnEditor(){editor();app.scrollTop=editorScroll}
function scopeMenu(){sheet(`<h2>谁可以看见</h2><p class="sub">私人或多个圈子；同行关联单独设置。</p><div class="choice-list" role="listbox" aria-label="可见范围" aria-multiselectable="true"><button class="choice-option ${!pendingScope.length?'chosen':''}" role="option" aria-selected="${!pendingScope.length}" onclick="pendingScope=[];scopeMenu()"><span>${icon('lock')} 私人 · 仅自己可见</span><i class="choice-mark">${!pendingScope.length?'✓':''}</i></button>${circles.map((c,i)=>`<button class="choice-option ${pendingScope.includes(c)?'chosen':''}" role="option" aria-selected="${pendingScope.includes(c)}" onclick="toggleScope(${i})"><span>${icon('people')} ${esc(c)}</span><i class="choice-mark">${pendingScope.includes(c)?'✓':''}</i></button>`).join('')}</div><button class="primary full" onclick="draft.scope=[...pendingScope];returnEditor()">确认范围</button>`)}
function toggleScope(i){let c=circles[i];pendingScope=pendingScope.includes(c)?pendingScope.filter(n=>n!==c):[...pendingScope,c];scopeMenu()}
let calendarYear=2026,calendarMonth=10;
function openCalendar(){let [y,m]=draft.date.split('-').map(Number);calendarYear=y;calendarMonth=m-1;calendarMenu()}
function calendarMenu(){let first=new Date(calendarYear,calendarMonth,1).getDay(),days=new Date(calendarYear,calendarMonth+1,0).getDate();sheet(`<h2>记忆时间</h2><div class="calendar-title">${ib('back','moveMonth(-1)','上个月')}<b>${calendarYear} 年 ${calendarMonth+1} 月</b>${ib('arrow','moveMonth(1)','下个月')}</div><div class="calendar-grid">${['日','一','二','三','四','五','六'].map(d=>`<span>${d}</span>`).join('')}${Array(first).fill('<span></span>').join('')}${Array.from({length:days},(_,i)=>{let d=i+1,date=`${calendarYear}-${String(calendarMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return `<button class="${date===draft.date?'chosen':''}" aria-label="${date}" onclick="draft.date='${date}';returnEditor()">${d}</button>`}).join('')}</div>`)}
function moveMonth(offset){calendarMonth+=offset;if(calendarMonth<0){calendarMonth=11;calendarYear--}if(calendarMonth>11){calendarMonth=0;calendarYear++}calendarMenu()}
